PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS state (id INTEGER PRIMARY KEY CHECK(id=1), draft TEXT NOT NULL, published TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1, published_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS versions (id TEXT PRIMARY KEY, content TEXT NOT NULL, created_at TEXT NOT NULL, label TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credentials (id INTEGER PRIMARY KEY CHECK(id=1), password TEXT, setup_hash TEXT, setup_expires INTEGER, gate_password TEXT, gate_revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS sessions (hash TEXT PRIMARY KEY, kind TEXT NOT NULL, expires INTEGER NOT NULL, gate_revision INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS session_expiry ON sessions(expires);
CREATE TABLE IF NOT EXISTS attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, name TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, folder TEXT NOT NULL, created_at TEXT NOT NULL, storage TEXT NOT NULL DEFAULT 'd1');
CREATE TABLE IF NOT EXISTS media_chunks (media_id TEXT NOT NULL REFERENCES media(id) ON DELETE CASCADE, part INTEGER NOT NULL, content TEXT NOT NULL, PRIMARY KEY(media_id,part));
